selector{
    background: radial-gradient(100% 256% at 100% 0%, #2B325C 0%, #101429 100%)
}

/* ajustes gerais do widget */
selector{
  text-wrap: balance;
  max-height: 300px;
  overflow-x: hidden;
  overflow-y: auto;
}

/* scrollbar opcional */
selector::-webkit-scrollbar{ width: 8px; }
selector::-webkit-scrollbar-track{ background: #919191; }
selector::-webkit-scrollbar-thumb{ background: #ffffff; }

/* ===== BULLETS PERSONALIZADOS =====
   Corrigido: classes encadeadas corretamente (.a.b), e escopo no widget (selector)
*/

/* remove bullets nativos */
selector .elementor-heading-title.elementor-size-default ul{
  list-style: none;
  margin: 0;
  padding: 0;
}

/* itens da lista */
selector .elementor-heading-title.elementor-size-default ul li{
  position: relative;
  padding-left:40px;       /* espaço para o ícone */
  line-height: 1.3;
  font-weight: 400;
  margin-top: 0px;
}

/* espaçamento entre itens (além do margin-top acima, se quiser mais fino) */
selector .elementor-heading-title.elementor-size-default ul li + li{
  margin-top: 26px;
}

/* ícone como bullet via mask (permite recolorir a SVG) */
selector .elementor-heading-title.elementor-size-default ul li::before{
  content: "";
  position: absolute;
  left: 0;
  top: 50%;                       /* centraliza verticalmente */
  transform: translateY(-50%);
  width: 28px;
  height: 28px;

  /* usa sua URL de ícone */
  -webkit-mask: url("https://ead.faculdadeide.edu.br/wp-content/uploads/2025/10/ICON-CHECKK-BOLLET-01.svg") no-repeat center / contain;
  mask: url("https://ead.faculdadeide.edu.br/wp-content/uploads/2025/10/ICON-CHECKK-BOLLET-01.svg") no-repeat center / contain;

  /* cor do ícone (dourado) */
  background-color: #ffffff;
}

/* Fallback p/ navegadores que não suportam mask */
@supports not (mask: url("")){
  selector .elementor-heading-title.elementor-size-default ul li::before{
    background-image: url("https://ead.faculdadeide.edu.br/wp-content/uploads/2025/10/ICON-ARROW-BOLLET-01.svg");
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    background-color: transparent;
  }
}


