.scroll-left{
    opacity: 0;
    transition: 0.9s all;
    transform: translate(-30px, 0);
}

.scroll-right{
    opacity: 0;
    transition: 0.9s all;
    transform: translate(30px, 0);
}

.scroll-bottom{
    opacity: 0;
    transition: 0.9s all;
    transform: translate(0, 80px);
}

.scroll-top{
    opacity: 0;
    transition: 0.9s all;
    transform: translate(0, -80px);
}

.scroll-opacitiy{
    opacity: 0;
    transition: 0.9s all;
}

.elementor-editor-active .scroll-bottom,
.elementor-editor-active .scroll-left,
.elementor-editor-active .scroll-right,
.elementor-editor-active .fade-on-target,
.ativo{
    opacity: 1;
    transition: 0.9s;
    transform: translatey(0px);
}

/* Elementos que devem sumir ao atingir a seção alvo */
.fade-on-target{
  transition: opacity .28s ease, transform .28s ease;
}
.fade-on-target.ativo{
  opacity: 0;
  pointer-events: none;     /* evita clique quando oculto */
  transform: translateY(-6px); /* opcional: leve deslocamento */
}

