html, body{ width: 100%; overflow-x: hidden; }

/* Transição do ícone do botão */
.elementor-button-icon {
  transition: transform 0.5s ease;
}

/* Rotação do ícone quando o botão é destacado */
.hovers:hover .elementor-button-icon {
  transform: rotate(-45deg);
}

.hovers_whats:hover .elementor-button-icon {
  transform: rotate(-5deg);
}

.hovers_whats .elementor-button-icon {
  width: 36px;
}

.hovers_whats:hover .elementor-button-text {
  transition: margin 0.3s ease;
  margin: 0px 4px 0px -4px;
}

/* Sombra do botão quando o botão é destacado */


/* Transição do texto do botão */
.hovers .elementor-button-text {
  transition: margin 0.3s ease;
}

/* Margem do texto do botão quando o botão é destacado */
.hovers:hover .elementor-button-text {
  margin: 0px 8px 0px -8px;
}

/* Elementos que vão sumir ao entrar na seção-alvo */
.fade-on-target{
  transition: opacity .28s ease, transform .28s ease;
}

/* Usado no modo A (toggle) */
.fade-on-target.is-hidden{
  opacity: 0;
  pointer-events: none;
